import {createProject,StudioStore,FORMATS,normalizeSlide,FORMATION_CONFIG,defaultContentForFormation,normalizeSlideContentForTemplate,BRAND_SLOGAN,DEFAULT_LOGO_SETTINGS} from './studio-store.js';
