const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const LEFT_SIDEBAR_MIN_WIDTH=220,LEFT_SIDEBAR_MAX_WIDTH=520,LEFT_SIDEBAR_COLLAPSED_WIDTH=64,LEFT_SIDEBAR_DEFAULT_WIDTH=280;
const ZOOM_MIN=20,ZOOM_MAX=160,ZOOM_STEP=5;
let studioInitialized=false,eventsBound=false,editing=null,logoDrag=null,elementGesture=null;
const cfg=JSON.parse($('#studio-config').textContent);window.STUDIO_BOOTSTRAP=window.STUDIO_BOOTSTRAP||cfg.bootstrap||{officialLogoUrl:'/static/img/logo-integrale.png',slogan:'Faites le premier pas vers votre futur métier',website:'www.integraleacademy.com',phone:'04 22 47 07 68',defaultBranding:{logoUrl:'/static/img/logo-integrale.png',slogan:'Faites le premier pas vers votre futur métier'}};const state={themes:cfg.themes,templates:cfg.templates,templateRegistry:null};state.templateRegistry=buildTemplateRegistry(state.templates);
const store=new StudioStore(createProject(cfg.defaultSlide),state.themes,state.templates);const exporter=new SocialVisualExporter({root:$('#studio-export-root'),themes:state.themes,templates:state.templates});
const STUDIO_PANELS=['models','content','branding','elements','media','data','ai','history','validation'];
const LEGACY_PANEL_IDS={templates:'models',brand:'branding',check:'validation'};
const PANEL_LABELS={models:'Modèles',content:'Contenu',branding:'Charte',elements:'Éléments',media:'Médias',data:'Données',ai:'IA',history:'Historique',validation:'Vérification'};
const ICON_CATEGORIES=['Sécurité','Incendie','Direction','Mobilité','Formation','Calendrier','Finance','Localisation','Certification','Emploi','Documents','Progression','Alerte','Validation'];
const EMOJI_LIBRARY=['🎃','👻','🕸️','🎄','✨','🎓','🛡️','🔥','🚘','📅','📍','💼','✅','⭐','🚀','📣','💡','🏆','🎯','⚡','🔒','☎️','👉','💶'];
const ALIGNMENT_SNAP_DISTANCE=10;
function getActiveSlide(){return store.slide}function readyTemplates(){return state.templates.filter(t=>t.status==='ready').sort((a,b)=>Number(Boolean(b.isNew))-Number(Boolean(a.isNew)))}function getActiveTemplate(){return state.templateRegistry[getActiveSlide().templateId]||readyTemplates()[0]}function getDefaultThemeForFormation(f){return (FORMATION_CONFIG[f]||FORMATION_CONFIG.APS).defaultThemeId}function getDefaultVariant(id){return state.templates.find(t=>t.id===id)?.supportedFormats?.[0]?'light':'light'}
function showToast(message,type='info'){let root=$('#studioToastRoot');if(!root){root=document.createElement('div');root.id='studioToastRoot';document.body.append(root)}const t=document.createElement('div');t.className=`studio-toast studio-toast--${type}`;t.textContent=message;root.append(t);setTimeout(()=>t.remove(),4200)}
async function studioFetch(url,options={}){const response=await fetch(url,{credentials:'same-origin',headers:{'X-Requested-With':'XMLHttpRequest',...(options.headers||{})},...options});const contentType=response.headers.get('content-type')||'';if(!response.ok){const body=contentType.includes('application/json')?await response.json().catch(()=>null):await response.text().catch(()=>'');throw new Error(body?.error||body?.message||`Erreur HTTP ${response.status}`)}return contentType.includes('application/json')?response.json():response}
async function loadStudioConfiguration(){restoreSidebar();optionize($('#inspectorFormation'),Object.keys(state.themes),x=>x,x=>FORMATION_CONFIG[x]?.label||x);optionize($('#inspectorTemplate'),state.templates.filter(t=>t.status==='ready'),t=>t.id,t=>t.name)}
async function loadInitialProject(){store.project.ui=store.project.ui||{};store.project.ui.activeLeftPanel=normalizeStudioPanelId(localStorage.getItem('studio.activeLeftPanel')||'models')}
function bindStudioEvents(){if(eventsBound)return;eventsBound=true;bindLeftNavigation();bindSidebarResize();bindHistoryShortcuts(store);setupAutosave(store,saveStudioProject,t=>$('#saveState').textContent=t);window.addEventListener('resize',applyZoom);store.addEventListener('change',renderStudio);document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);document.addEventListener('keydown',handleKeydown);document.addEventListener('pointerdown',handlePointerDown);document.addEventListener('pointermove',handlePointerMove);document.addEventListener('pointerup',handlePointerUp);document.addEventListener('pointercancel',handlePointerUp);}
async function initStudio(){if(studioInitialized)return;studioInitialized=true;try{await loadStudioConfiguration();await loadInitialProject();bindStudioEvents();await renderStudio();markStudioAsReady()}catch(error){console.error('[STUDIO] Initialisation impossible',error);showStudioFatalError(error)}}
document.addEventListener('DOMContentLoaded',initStudio);
function markStudioAsReady(){document.body.classList.add('studio-ready')}function showStudioFatalError(e){showToast(`Studio indisponible : ${e.message}`,'error')}
function optionize(sel,items,getV=x=>x,getT=x=>x){sel.innerHTML='';items.forEach(x=>sel.append(new Option(getT(x),getV(x))))}
function renderFormatNetworkHint(){const format=FORMATS[store.project.format?.id]||store.project.format||FORMATS.instagram_square,hint=$('#formatNetworkHint');if(hint)hint.textContent=`${format.networks||'Réseaux sociaux'} · ${format.usage||format.label||''}`}
async function renderStudio(){const p=store.project;$('#projectName').value=p.name;$('#formatSelect').value=p.format.id;renderFormatNetworkHint();syncAllControlsFromState();await renderActiveSlide();applyZoom();renderLeft();renderFilmstrip();renderInspector();renderQuality();renderAiDesignStatus()}
async function renderActiveSlide(){const p=store.project,slide=getActiveSlide(),tpl=state.templates.find(t=>t.id===slide.templateId);const canvas=$('#studio-canvas');canvas.style.width=p.format.width+'px';canvas.style.height=p.format.height+'px';if(!tpl){canvas.replaceChildren(Object.assign(document.createElement('p'),{textContent:`Le template « ${slide.templateId} » n’a pas pu être chargé.`}));return}const node=renderSlide(p,slide,'preview',state);canvas.replaceChildren(node);if(canvas.querySelector('[data-rendered-template-id]')?.dataset.renderedTemplateId!==slide.templateId)showToast(`Le rendu ne correspond pas au template ${slide.templateId}`,'error');makeCanvasElementsInteractive();await fitSlide(node).catch(e=>console.warn('[STUDIO] Texte non ajusté',e));runValidation();}
function syncAllControlsFromState(){const p=store.project,s=getActiveSlide();$('#inspectorFormation').value=p.formation;$('#inspectorTemplate').value=s.templateId;$('#showLogo').checked=p.branding.logoVisible!==false;$('#showSafe').checked=s.options.showSafeMargins!==false;}
function setFormation(formationId){const cfg=FORMATION_CONFIG[formationId];if(!cfg){showToast(`Thème inconnu : ${formationId}`,'error');return}store.commit(`Thème changé en ${cfg.label}`,p=>{p.formation=formationId;p.themeId=cfg.defaultThemeId;const s=p.slides[p.activeSlideIndex];if(!s.content._manual||s.content._autoFormation!==formationId){s.content={...defaultContentForFormation(formationId),footer:{...s.content.footer}}}else{s.content._incompatibleFormation=s.content._autoFormation}s.content.eyebrow=formationId==='OR'?'INTÉGRALE ACADEMY':`FORMATION ${formationId}`;s.content.highlightedText=formationId==='OR'?'INTÉGRALE':formationId;},'formation-change');showToast(`Thème ${cfg.label} appliqué`,'success')}
function setTemplate(templateId){const template=state.templateRegistry[templateId];if(!template){showToast(`Le template ${templateId} est introuvable.`,'error');return}store.commit(`Template « ${template.name} » appliqué`,p=>{const slide=p.slides[p.activeSlideIndex];if(template.formationPreset&&FORMATION_CONFIG[template.formationPreset]){const preset=template.formationPreset;p.formation=preset;p.themeId=getDefaultThemeForFormation(preset);if(!slide.content._manual)slide.content={...defaultContentForFormation(preset),footer:{...slide.content.footer}};slide.content.highlightedText=template.giantLetters||preset;slide.content._autoFormation=preset}slide.templateId=templateId;slide.templateVariant=getDefaultVariant(templateId);normalizeSlideContentForTemplate(slide,template);p.usedTemplateIds=[...(p.usedTemplateIds||[]),templateId].slice(-20);p.usedFamilies=[...(p.usedFamilies||[]),template.family].slice(-20);},'template-change');showToast(`Template appliqué : ${template.name}`,'success')}
function chooseDifferentComposition(){const current=getActiveTemplate();let candidates=recommendTemplates(getActiveSlide().content,{role:getActiveSlide().role}).map(id=>state.templateRegistry[id]).filter(Boolean).filter(t=>t.id!==current.id&&t.family!==current.family);if(!candidates.length)candidates=readyTemplates().filter(t=>t.id!==current.id&&t.family!==current.family);const used=store.project.usedTemplateIds||[];candidates.sort((a,b)=>used.indexOf(a.id)-used.indexOf(b.id));const next=candidates[0];if(next){setTemplate(next.id);showToast(`Composition totalement changée : ${next.name}`,'success')}}
function normalizeStudioPanelId(panelId){return LEGACY_PANEL_IDS[panelId]||panelId}
function bindLeftNavigation(){const navigation=$('[data-studio-navigation]');if(!navigation)return;navigation.addEventListener('click',event=>{const button=event.target.closest('[data-studio-panel]');if(!button)return;openStudioSidebarPanel(button.dataset.studioPanel)})}
function openStudioSidebarPanel(panelId,{render=true}={}){panelId=normalizeStudioPanelId(panelId);if(!STUDIO_PANELS.includes(panelId))panelId='models';store.project.ui=store.project.ui||{};store.project.ui.activeLeftPanel=panelId;localStorage.setItem('studio.activeLeftPanel',panelId);$$('[data-studio-panel]').forEach(button=>{const isActive=button.dataset.studioPanel===panelId;button.classList.toggle('is-active',isActive);button.setAttribute('aria-selected',String(isActive))});$$('[data-studio-panel-content]').forEach(panel=>{const isActive=panel.dataset.studioPanelContent===panelId;panel.hidden=!isActive;panel.classList.toggle('is-active',isActive)});if(render)renderLeft()}
const openLeftPanel=openStudioSidebarPanel
function bindSidebarResize(){const resizer=$('#studio-left-resizer'),sidebar=$('#studio-left-sidebar'),toggle=$('#studio-left-toggle');resizer.addEventListener('pointerdown',e=>{if(sidebar.classList.contains('is-collapsed'))return;e.preventDefault();resizer.setPointerCapture(e.pointerId);document.body.classList.add('studio-is-resizing');logoDrag={type:'sidebar',startX:e.clientX,startWidth:sidebar.offsetWidth}});resizer.addEventListener('pointermove',e=>{if(!logoDrag||logoDrag.type!=='sidebar')return;setSidebarWidth(Math.min(LEFT_SIDEBAR_MAX_WIDTH,Math.max(LEFT_SIDEBAR_MIN_WIDTH,logoDrag.startWidth+e.clientX-logoDrag.startX)))});resizer.addEventListener('pointerup',()=>{if(logoDrag?.type==='sidebar'){localStorage.setItem('studio.leftSidebarWidth',String(store.project.ui.leftSidebarWidth));document.body.classList.remove('studio-is-resizing');logoDrag=null}});resizer.addEventListener('dblclick',()=>setSidebarWidth(LEFT_SIDEBAR_DEFAULT_WIDTH,true));toggle.addEventListener('click',()=>setSidebarCollapsed(!store.project.ui.leftSidebarCollapsed))}
function setSidebarWidth(w,persist=false){store.project.ui.leftSidebarWidth=w;$('#studio-layout').style.setProperty('--left-sidebar-width',w+'px');if(persist)localStorage.setItem('studio.leftSidebarWidth',String(w))}
function setSidebarCollapsed(v){store.project.ui.leftSidebarCollapsed=v;$('#studio-left-sidebar').classList.toggle('is-collapsed',v);$('#studio-layout').classList.toggle('studio-left-collapsed',v);localStorage.setItem('studio.leftSidebarCollapsed',String(v));$('#studio-left-toggle').textContent=v?'Ouvrir':'Réduire'}
function restoreSidebar(){store.project.ui=store.project.ui||{};setSidebarWidth(Math.min(LEFT_SIDEBAR_MAX_WIDTH,Math.max(LEFT_SIDEBAR_MIN_WIDTH,Number(localStorage.getItem('studio.leftSidebarWidth'))||LEFT_SIDEBAR_DEFAULT_WIDTH)));setSidebarCollapsed(localStorage.getItem('studio.leftSidebarCollapsed')==='true')}
function renderLeft(){renderStudioSidebarPanelEnhanced(store.project.ui?.activeLeftPanel||'models')}
function templatePreviewMarkup(template){if(!template.isNew)return `<img src="${esc(template.thumbnail||window.STUDIO_BOOTSTRAP.officialLogoUrl)}" alt="Aperçu du modèle ${esc(template.name)}" onerror="this.style.display='none'">`;const index=Number(template.previewStyle)||1,palette=['#087A55','#0057D8','#D71920','#D96900','#6D28D9'],color=palette[(index-1)%palette.length],x=18+(index*17)%68,y=20+(index*23)%60,rotation=(index%9-4)*7,titleRotation=(index%5-2)*3,radius=index%4===0?'50%':index%3===0?'8px 28px':'24px';return `<div class="studio-template-live-preview preview-${index}" style="--pv-color:${color};--pv-x:${x}%;--pv-y:${y}%;--pv-rotate:${rotation}deg;--pv-title-rotate:${titleRotation}deg;--pv-r:${radius}"><i></i><b></b><span></span><em></em></div><span class="studio-new-badge">NEW</span>`}
function renderStudioSidebarPanel(tab){tab=normalizeStudioPanelId(tab);openStudioSidebarPanel(tab,{render:false});const panel=$(`[data-studio-panel-content="${tab}"]`),s=getActiveSlide(),c=s.content;if(!panel)return;if(tab==='models'){const rec=recommendTemplates(c,{role:s.role}).slice(0,3);panel.innerHTML=`<div class="studio-template-toolbar"><button type="button" data-action="differentComposition">Changer totalement de composition</button><div class="studio-recommendations"><strong>Recommandé pour ce contenu</strong>${rec.map((id,i)=>{const t=state.templateRegistry[id];return t?`<button type="button" data-template-id="${id}">${i+1}. ${esc(t.name)}</button>`:''}).join('')}</div></div><div class="social-studio__template-grid" data-models-gallery>${readyTemplates().map(t=>`<button type="button" class="social-studio__template-card studio-model-card ${t.id===s.templateId?'is-active':''}" data-template-id="${t.id}" data-new-template="${String(Boolean(t.isNew))}">${templatePreviewMarkup(t)}<b>${esc(t.name)}</b><small>${esc(t.family)}</small><div class="studio-template-card-meta"><span>${esc(t.density||'')}</span><span>${esc(t.style||'')}</span></div></button>`).join('')}</div>`;}if(tab==='content')panel.innerHTML=renderTemplateContentFields(getActiveTemplate(),c);if(tab==='branding'){const th=state.themes[store.project.formation];panel.innerHTML=`<label>Formation<select id="brandFormation">${Object.keys(state.themes).map(f=>`<option ${f===store.project.formation?'selected':''}>${f}</option>`).join('')}</select></label><p>Thème : ${esc(store.project.themeId)}</p><p>Formation active : ${esc(store.project.formation)}</p><p>Couleurs : ${esc(th.primary)} / ${esc(th.accent)}</p><label><input type="checkbox" id="gridToggle"> Quadrillage</label><p>Charte verrouillée</p>`}if(tab==='elements')panel.innerHTML=ICON_CATEGORIES.map((x,i)=>`<button data-add-icon="${esc(x)}">${esc(x)}</button>`).join('');if(tab==='media')panel.innerHTML=`<label class="studio-upload">Importer un logo<input id="logoInput" type="file" accept=".png,.svg,.webp,.jpg,.jpeg,image/png,image/svg+xml,image/webp,image/jpeg"></label><div class="studio-logo-meta"><img class="studio-logo-preview" src="${store.project.branding.logoUrl}"><strong>${store.project.branding.logoName||'Logo officiel Intégrale Academy'}</strong><small>Logo actif sur toutes les slides</small><button data-action="logoOfficial">Revenir au logo officiel</button></div>`;if(tab==='data')panel.innerHTML=['date','examDate','location','duration','price','financing','availability'].map(k=>field(`data.${k}`,k,c[k]||'')).join('');if(tab==='ai')panel.innerHTML=`<textarea id="aiTopic" placeholder="Annonce session APS septembre 2026"></textarea>${['Générer le contenu','Générer trois titres','Raccourcir le texte','Corriger l’orthographe','Créer un carrousel','Proposer un template'].map(a=>`<button data-ai="${a}">${a}</button>`).join('')}`;if(tab==='history')panel.innerHTML='<div class="studio-history-list">'+(store.history.slice(-20).reverse().map(h=>`<div class="studio-history-entry"><span class="studio-history-icon">•</span><div><strong>${esc(h.label||'Action')}</strong><small>${new Date(h.at||Date.now()).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join('')||'<p>Aucune action.</p>')+'</div>'; if(tab==='validation')panel.innerHTML=$('#qualityPanel').innerHTML}

function iconPreview(label=''){const key=String(label).toLowerCase();if(key.includes('incendie'))return '🔥';if(key.includes('mobilité'))return '🚘';if(key.includes('calendrier'))return '📅';if(key.includes('finance'))return '€';if(key.includes('localisation'))return '📍';if(key.includes('certification')||key.includes('validation'))return '✓';if(key.includes('emploi'))return '💼';if(key.includes('documents'))return '▣';if(key.includes('progression'))return '↗';if(key.includes('alerte'))return '!';if(key.includes('direction'))return '★';if(key.includes('formation'))return '✦';return '◆'}
function renderStudioSidebarPanelEnhanced(tab){renderStudioSidebarPanel(tab);tab=normalizeStudioPanelId(tab);const panel=$(`[data-studio-panel-content="${tab}"]`);if(!panel)return;if(tab==='branding'){const th=state.themes[store.project.formation]||state.themes.OR;panel.innerHTML=`<label>Formation ou thème<select id="brandFormation">${Object.keys(state.themes).map(f=>`<option value="${f}" ${f===store.project.formation?'selected':''}>${esc(FORMATION_CONFIG[f]?.label||f)}</option>`).join('')}</select></label><p><strong>${esc(FORMATION_CONFIG[store.project.formation]?.label||store.project.formation)}</strong></p><p>${esc(th.positioning||'Identité Intégrale Academy')}</p><div class="studio-theme-swatches"><i style="background:${esc(th.primary)}"></i><i style="background:${esc(th.secondary)}"></i><i style="background:${esc(th.accent)}"></i><i style="background:${esc(th.surfaceDark)}"></i></div><label><input type="checkbox" id="gridToggle"> Quadrillage</label><p>Charte verrouillée</p>`}if(tab==='elements')panel.innerHTML=`<div class="studio-elements-library"><h3>Emojis</h3><div class="studio-emoji-grid">${EMOJI_LIBRARY.map(x=>`<button type="button" data-add-emoji="${x}" title="Ajouter ${x}">${x}</button>`).join('')}</div><h3>Pictogrammes</h3><div class="studio-pictogram-grid">${ICON_CATEGORIES.map(x=>`<button type="button" data-add-icon="${esc(x)}"><span>${iconPreview(x)}</span>${esc(x)}</button>`).join('')}</div><p>Après ajout, sélectionnez l’élément pour le déplacer, le redimensionner, le tourner ou changer son opacité.</p></div>`;if(tab==='media')panel.innerHTML=`<label class="studio-upload">Ajouter une photo ou un visuel au template<input id="visualInput" type="file" accept=".png,.svg,.webp,.jpg,.jpeg,image/png,image/svg+xml,image/webp,image/jpeg"></label><small>PNG, JPG, WebP ou SVG · 5 Mo maximum. Le visuel ajouté devient librement déplaçable et redimensionnable.</small><hr><label class="studio-upload">Remplacer le logo<input id="logoInput" type="file" accept=".png,.svg,.webp,.jpg,.jpeg,image/png,image/svg+xml,image/webp,image/jpeg"></label><div class="studio-logo-meta"><img class="studio-logo-preview" src="${store.project.branding.logoUrl}"><strong>${store.project.branding.logoName||'Logo officiel Intégrale Academy'}</strong><small>Logo actif sur toutes les slides</small><button data-action="logoOfficial">Revenir au logo officiel</button></div>`;if(tab==='ai')panel.insertAdjacentHTML('afterbegin','<p>Générez le texte ici, ou utilisez <strong>Modifier avec l’IA</strong> sous le template pour transformer son univers visuel.</p>')}

function renderTemplateContentFields(template,c){const supported=template?.supportedContent||['title','introduction','cta'];const labels={eyebrow:'Surtitre',title:'Titre',highlightedText:'Mot/sigle surligné',introduction:'Introduction',cta:'Appel à l’action',quote:'Citation',author:'Auteur',startDate:'Date de début',endDate:'Date de fin',examDate:'Date d’examen',date:'Date',location:'Lieu',availability:'Places disponibles',duration:'Durée',financing:'Financement',daysRemaining:'Jours ou places restantes',sessionNumber:'Numéro de session',before:'Avant',after:'Après',question:'Question',answer:'Réponse',explanation:'Explication'};let html=`<p><strong>${esc(template?.name||'Template')}</strong><br><small>Champs adaptés au modèle sélectionné. Les autres données restent conservées.</small></p>`;for(const k of supported){if(k==='stats'){html+=`<h3>Statistiques</h3>${statsEditor(c)}`;continue}if(k==='steps'){html+=`<h3>Étapes</h3>${listEditor('steps',c.steps||[],['title','text'])}`;continue}if(k==='modules'){html+=`<h3>Modules</h3>${listEditor('modules',c.modules||[],['title','duration'])}`;continue}if(k==='faq'){html+=`<h3>FAQ</h3>${listEditor('faq',c.faq||[],['q','a'])}`;continue}if(k==='footer'){html+=`${field('footer.website','Site',c.footer?.website)}${field('footer.phone','Téléphone',c.footer?.phone)}`;continue}html+=field(k,labels[k]||k,c[k]||'', ['title','introduction','quote','explanation'].includes(k)?'textarea':'input')}return html}
function statsEditor(c){const data=c.stats||[];return data.map((s,i)=>`${field(`stats.${i}.label`,`Libellé ${i+1}`,s.label)}${field(`stats.${i}.value`,`Valeur ${i+1}`,s.value)}`).join('')||'<p>Aucune statistique. Ajoutez-en dans les données du projet.</p>'}
function listEditor(name,items,keys){const seed=items.length?items:[{}];return seed.map((it,i)=>keys.map(k=>field(`${name}.${i}.${k}`,`${name} ${i+1} — ${k}`,it[k]||'')).join('')).join('')}

function field(k,l,v,type='input'){return `<label>${l}${type==='textarea'?`<textarea data-content="${k}">${esc(v)}</textarea>`:`<input data-content="${k}" value="${esc(v)}">`}</label>`}
function renderFilmstrip(){$('#filmstrip').innerHTML=store.project.slides.map((s,i)=>`<button class="social-studio__thumb ${i===store.project.activeSlideIndex?'is-active':''}" data-slide="${i}">${i+1}<br><small>${esc(s.templateId)}</small></button>`).join('')+'<button data-action="addSlide">+ Slide</button>'}
function runValidation(){const node=$('#studio-canvas .social-studio-slide');if(!node)return {blockingErrors:[],warnings:[],info:[]};const rendered=validateStudioSlide(node);const projectIssues=validateProject(store.project);renderValidationPanel(rendered,projectIssues);return rendered}function renderQuality(){runValidation()}function renderValidationPanel(v,projectIssues=[]){store.project.validation={errors:v.blockingErrors,warnings:[...v.warnings,...projectIssues]};const html='<h3>Vérification</h3><button type="button" data-action="autoFix">Corriger automatiquement</button>'+v.info.map(i=>`<div class="social-studio__ok">✓ ${esc(i.message)}</div>`).join('')+v.warnings.map(i=>`<div class="social-studio__warning">⚠ ${esc(i.message)}</div>`).join('')+projectIssues.map(i=>`<div class="social-studio__warning">⚠ ${esc(i.message)}</div>`).join('')+v.blockingErrors.map(i=>`<button class="social-studio__error" data-select-error>✕ ${esc(i.message)}</button>`).join('')+(!v.blockingErrors.length?'<p>✅ Aucun problème bloquant détecté.</p>':'');$('#qualityPanel').innerHTML=html;const check=$('[data-studio-panel-content="validation"]');if(check&&!check.hidden)check.innerHTML=html;}
function escapeSelector(value){return globalThis.CSS?.escape?CSS.escape(String(value)):String(value).replace(/["\\]/g,'\\$&')}
function selectedCanvasElement(id=store.project.ui?.selectedElementId){return id?$('#studio-canvas')?.querySelector(`[data-studio-element-id="${escapeSelector(id)}"]`):null}
function installElementResizeHandle(el){$$('.studio-element-resize').forEach(handle=>handle.remove());if(!el||el.matches('[data-logo-id],svg'))return;if(window.getComputedStyle(el).position==='static')el.style.position='relative';const handle=document.createElement('i');handle.className='studio-element-resize';handle.dataset.elementResize='true';handle.dataset.editorOnly='true';handle.title='Agrandir ou réduire cet élément';handle.setAttribute('aria-label','Agrandir ou réduire cet élément');el.append(handle)}
function normalizedElementProperty(prop,raw){const value=Number(raw);if(prop==='scale'||prop==='opacity')return value/100;return value}
function elementOutput(prop,value){if(prop==='scale'||prop==='opacity')return `${Math.round(Number(value)*100)} %`;if(prop==='rotation')return `${Math.round(Number(value))}°`;if(prop==='fontSize')return `${Math.round(Number(value))} px`;return `${Math.round(Number(value))} px`}
function renderInspector(){const id=store.project.ui?.selectedElementId,slide=getActiveSlide(),box=$('#inspectorContext'),node=selectedCanvasElement(id);if(!id||!node){box.innerHTML='<p>Sélectionnez un élément pour afficher ses propriétés.</p>';return}const override=getElementOverride(slide,id),isLogo=node.matches('[data-logo-id]'),isText=node.dataset.studioTextEditable==='true',name=node.dataset.studioElementName||'Élément',computed=window.getComputedStyle(node),scale=Number(override.scale)||1,opacity=Number.isFinite(Number(override.opacity))?Number(override.opacity):(Number.parseFloat(computed.opacity)||1),fontSize=Number(override.fontSize)||Number.parseFloat(computed.fontSize)||32,rotation=Number(override.rotation)||0,x=Number(override.x)||0,y=Number(override.y)||0,textValue=override.text!==undefined?override.text:String(node.textContent||'').trim(),contentKey=node.dataset.contentKey||'';const logo=isLogo?getSlideLogo(slide):null;box.innerHTML=`<div class="studio-element-controls"><span class="studio-element-controls__type">${isLogo?'Identité visuelle':isText?'Texte modifiable':'Bloc de mise en page'}</span><h3>${esc(name)}</h3>${isText?`<label>Texte<textarea data-element-text="true"${contentKey?` data-element-content-key="${esc(contentKey)}"`:''}>${esc(textValue)}</textarea></label>`:''}${isLogo?`<label class="studio-logo-slider"><span>Largeur du logo <output>${Math.round(logo.width)} px</output></span><input data-logo-prop="width" type="range" min="60" max="320" step="5" value="${logo.width}"></label><div class="studio-logo-size-actions"><button type="button" data-action="logoSmaller">− Petit</button><button type="button" data-action="logoReset">Taille idéale</button><button type="button" data-action="logoLarger">+ Grand</button></div>`:''}<div class="studio-element-controls__grid"><label><span>Position X <output>${Math.round(x)} px</output></span><input data-element-prop="x" type="number" min="-1080" max="1080" step="1" value="${x}"></label><label><span>Position Y <output>${Math.round(y)} px</output></span><input data-element-prop="y" type="number" min="-1920" max="1920" step="1" value="${y}"></label></div><label><span>Échelle <output>${Math.round(scale*100)} %</output></span><input data-element-prop="scale" type="range" min="20" max="300" step="1" value="${Math.round(scale*100)}"></label>${isText?`<label><span>Taille du texte <output>${Math.round(fontSize)} px</output></span><input data-element-prop="fontSize" type="range" min="8" max="220" step="1" value="${Math.round(fontSize)}"></label>`:''}<label><span>Rotation <output>${Math.round(rotation)}°</output></span><input data-element-prop="rotation" type="range" min="-180" max="180" step="1" value="${rotation}"></label><label><span>Opacité <output>${Math.round(opacity*100)} %</output></span><input data-element-prop="opacity" type="range" min="5" max="100" step="1" value="${Math.round(opacity*100)}"></label><div class="studio-element-controls__actions"><button type="button" data-action="elementBackward">Arrière-plan</button><button type="button" data-action="elementForward">Premier plan</button><button type="button" data-action="elementReset">Réinitialiser cet élément</button></div><p class="studio-element-help">Glissez l’élément pour le déplacer. Utilisez la poignée bleue pour changer sa taille. Double-cliquez sur un texte pour l’éditer directement.</p></div>`}
function ensureAlignmentGuides(root){if(!root||root.querySelector('.studio-alignment-overlay'))return;const overlay=document.createElement('div');overlay.className='studio-alignment-overlay';overlay.dataset.editorOnly='true';overlay.innerHTML='<div class="studio-canvas-ruler studio-canvas-ruler--top"></div><div class="studio-canvas-ruler studio-canvas-ruler--left"></div><i class="studio-alignment-guide studio-alignment-guide--x"></i><i class="studio-alignment-guide studio-alignment-guide--y"></i><span class="studio-alignment-guide__label">Centré</span>';root.append(overlay)}
function showAlignmentGuides({x=false,y=false,label='Centré'}={}){const overlay=$('#studio-canvas .studio-alignment-overlay');if(!overlay)return;overlay.classList.toggle('show-x',Boolean(x));overlay.classList.toggle('show-y',Boolean(y));const text=overlay.querySelector('.studio-alignment-guide__label');if(text)text.textContent=label;overlay.classList.toggle('is-active',Boolean(x||y))}
function hideAlignmentGuides(){showAlignmentGuides()}
function makeCanvasElementsInteractive(){const root=$('#studio-canvas .social-studio-slide');if(!root)return;decorateEditableElements(root,getActiveSlide(),{renderMode:'preview'});ensureAlignmentGuides(root);const selected=selectedCanvasElement();if(selected){selected.classList.add('studio-selected');installElementResizeHandle(selected)}}
function selectElement(el){if(!el?.dataset?.studioElementId)return;store.project.ui=store.project.ui||{};store.project.ui.selectedElementId=el.dataset.studioElementId;$$('.studio-selected').forEach(x=>x.classList.remove('studio-selected'));el.classList.add('studio-selected');installElementResizeHandle(el);renderInspector()}
function startInlineTextEdit(el){if(!el||el.dataset.studioTextEditable!=='true')return;selectElement(el);const handle=el.querySelector(':scope > [data-editor-only]');handle?.remove();editing={el,old:el.textContent};el.contentEditable='plaintext-only';el.focus();document.execCommand?.('selectAll',false,null)}
function commitInlineTextEdit(el){if(!editing)return;const key=el.dataset.contentKey,value=el.textContent.trim(),id=el.dataset.studioElementId;editing=null;el.removeAttribute('contenteditable');if(key)setContentValue(key,value,'Texte modifié');else store.commit('Texte modifié',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{text:value}),'element-change');showToast('Texte modifié','success')}
function cancelInlineTextEdit(){if(!editing)return;const el=editing.el;el.textContent=editing.old;el.removeAttribute('contenteditable');editing=null;installElementResizeHandle(el);showToast('Modification annulée','info')}
function getContentValue(path){return path.split('.').reduce((o,k)=>o?.[k],getActiveSlide().content)??''}
function setContentValue(path,value,label='Contenu modifié'){store.commit(label,p=>{const parts=path.split('.');let o=p.slides[p.activeSlideIndex].content;while(parts.length>1){const k=parts.shift();o[k]=o[k]||{};o=o[k]}o[parts[0]]=value;o._manual=true})}
async function saveStudioProject(){if(store.project.ui?.isSaving)return;store.project.ui.isSaving=true;try{const j=await studioFetch('/api/admin/social-visuals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({post:store.project})});store.project.id=j.post.id;store.dirty=false;return j}catch(e){console.error('[STUDIO] Échec de sauvegarde',e);showToast(`Enregistrement impossible : ${e.message}`,'error');throw e}finally{store.project.ui.isSaving=false}}
async function importLogo(file){const fd=new FormData();fd.append('file',file);fd.append('type','logo');const j=await studioFetch('/api/admin/studio/media',{method:'POST',body:fd});store.commit('Logo ajouté',p=>{p.branding.logoUrl=j.media.url;p.branding.logoName=file.name;p.branding.logoVisible=true});showToast('Logo importé','success')}
async function importVisual(file){const fd=new FormData();fd.append('file',file);fd.append('type','visual');const j=await studioFetch('/api/admin/studio/media',{method:'POST',body:fd});store.commit('Visuel ajouté',p=>{const slide=p.slides[p.activeSlideIndex],count=(slide.elements||[]).length;slide.elements=slide.elements||[];slide.elements.push({id:crypto.randomUUID(),type:'image',url:j.media.url,label:file.name,x:120+(count%4)*36,y:170+(count%5)*34,width:260})},'media-add');showToast('Photo ou visuel ajouté au template','success')}
function renderAiDesignStatus(){const status=$('#aiDesignStatus'),design=getActiveSlide().options?.aiArtDirection;if(!status)return;status.textContent=design?`Direction artistique active : ${design.label||design.id||'personnalisée'}. Les éléments ajoutés restent modifiables.`:''}
async function applyAiDesignPrompt(){const input=$('#aiDesignPrompt'),prompt=String(input?.value||'').trim(),status=$('#aiDesignStatus');if(!prompt){showToast('Décrivez d’abord la transformation souhaitée.','info');input?.focus();return}if(status)status.textContent='L’IA prépare une nouvelle direction artistique…';try{const response=await studioFetch('/api/admin/studio/ai-transform',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,formation:store.project.formation,templateId:getActiveSlide().templateId})});const design=response.design||response;store.commit(`Direction artistique IA : ${design.label||'personnalisée'}`,p=>{const slide=p.slides[p.activeSlideIndex],width=Number(p.format?.width)||1080,height=Number(p.format?.height)||1080,positions=[[.08,.28],[.84,.3],[.12,.66],[.8,.64],[.47,.23],[.5,.72]];slide.options=slide.options||{};slide.options.aiArtDirection=design;slide.elements=(slide.elements||[]).filter(element=>element.source!=='ai-transform');for(const [index,glyph] of (design.decorations||[]).slice(0,6).entries()){const [left,top]=positions[index]||[.12+index*.12,.25+index*.08],fontSize=index===0?82:64;slide.elements.push({id:crypto.randomUUID(),type:'emoji',glyph,label:`Décoration ${design.label||'IA'}`,source:'ai-transform',x:Math.round(Math.min(width-fontSize-24,Math.max(24,width*left))),y:Math.round(Math.min(height-fontSize-24,Math.max(24,height*top))),fontSize})}},'ai-design');if(status)status.textContent=`Transformation appliquée : ${design.label||'direction artistique personnalisée'}.`;showToast('Le template a été transformé avec l’IA','success')}catch(error){if(status)status.textContent='La transformation n’a pas pu être appliquée.';showToast(`IA impossible : ${error.message}`,'error')}}
function resetAiDesign(){store.commit('Direction artistique IA réinitialisée',p=>{const slide=p.slides[p.activeSlideIndex];if(slide.options)delete slide.options.aiArtDirection;slide.elements=(slide.elements||[]).filter(element=>element.source!=='ai-transform')},'ai-design');showToast('Direction artistique d’origine restaurée','success')}
async function doExport(scale=1){if(store.project.ui?.isExporting)return;store.project.ui.isExporting=true;const buttons=$$('[data-action="exportStandard"],[data-action="exportHd"]'),outputWidth=store.project.format.width*scale,outputHeight=store.project.format.height*scale;try{buttons.forEach(button=>button.disabled=true);$('#exportMessage').textContent='Préparation…';const data=await exporter.exportSlide({project:store.project,slide:getActiveSlide(),outputWidth,outputHeight,type:'png',onStatus:m=>$('#exportMessage').textContent=m});const a=document.createElement('a');a.href=data;a.download=($('#exportFilename').value||'studio-visuel')+(scale===2?'-hd':'')+'.png';a.click();$('#exportMessage').textContent=`Export terminé : ${outputWidth} × ${outputHeight}`;showToast('Export terminé','success')}catch(e){console.error('[STUDIO] Export impossible',e);$('#exportMessage').textContent=`Export impossible : ${e.message}`;showToast(`Erreur pendant l’export : ${e.message}`,'error')}finally{buttons.forEach(button=>button.disabled=false);store.project.ui.isExporting=false}}

function getSlideLogo(slide=getActiveSlide()){slide.logo=slide.logo||{...DEFAULT_LOGO_SETTINGS};clampLogo(slide.logo);return slide.logo}
function clampLogo(logo){logo.width=Math.max(60,Math.min(320,Number(logo.width)||DEFAULT_LOGO_SETTINGS.width));logo.opacity=Math.max(.2,Math.min(1,Number.isFinite(Number(logo.opacity))?Number(logo.opacity):DEFAULT_LOGO_SETTINGS.opacity));return logo}
function updateLogoPreview(logo){const node=$('#studio-canvas [data-logo-id]');if(node){node.style.setProperty('--studio-logo-size',`${logo.width}px`);node.style.opacity=logo.opacity}const sizeOutput=$('[data-logo-prop="width"]')?.closest('label')?.querySelector('output');const opacityOutput=$('[data-logo-prop="opacity"]')?.closest('label')?.querySelector('output');if(sizeOutput)sizeOutput.textContent=`${Math.round(logo.width)} px`;if(opacityOutput)opacityOutput.textContent=`${Math.round(logo.opacity*100)} %`}
function changeLogoSize(delta,label='Taille du logo modifiée'){store.commit(label,p=>{const logo=getSlideLogo(p.slides[p.activeSlideIndex]);logo.width+=delta;clampLogo(logo)},'logo-change')}
function handlePointerDown(e){if(editing)return;const el=e.target.closest?.('#studio-canvas [data-studio-element-id]');if(!el)return;selectElement(el);const id=el.dataset.studioElementId,override=getElementOverride(getActiveSlide(),id),zoom=Math.max(.1,Number(store.project.ui?.zoomValue)||1),canvasRect=$('#studio-canvas').getBoundingClientRect(),rect=el.getBoundingClientRect(),logoResize=e.target.closest('[data-logo-resize]'),elementResize=e.target.closest('[data-element-resize]');elementGesture={type:logoResize?'logo-width':elementResize?'scale':'move',id,el,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,startOverride:override,startScale:Number(override.scale)||1,startLogo:{...getSlideLogo()},zoom,moved:false,startCenter:{x:(rect.left-canvasRect.left+rect.width/2)/zoom,y:(rect.top-canvasRect.top+rect.height/2)/zoom},canvasSize:{width:canvasRect.width/zoom,height:canvasRect.height/zoom},bounds:{minX:-(rect.left-canvasRect.left)/zoom,maxX:(canvasRect.right-rect.right)/zoom,minY:-(rect.top-canvasRect.top)/zoom,maxY:(canvasRect.bottom-rect.bottom)/zoom}};el.setPointerCapture?.(e.pointerId);if(logoResize||elementResize)e.preventDefault()}
function snapElementMove(g,moveX,moveY){const targetX=g.canvasSize.width/2,targetY=g.canvasSize.height/2,deltaX=targetX-(g.startCenter.x+moveX),deltaY=targetY-(g.startCenter.y+moveY),snapX=Math.abs(deltaX)<=ALIGNMENT_SNAP_DISTANCE,snapY=Math.abs(deltaY)<=ALIGNMENT_SNAP_DISTANCE;if(snapX)moveX+=deltaX;if(snapY)moveY+=deltaY;showAlignmentGuides({x:snapX,y:snapY,label:snapX&&snapY?'Centré horizontalement et verticalement':snapX?'Centré horizontalement':'Centré verticalement'});return {moveX,moveY}}
function handlePointerMove(e){if(!elementGesture||elementGesture.pointerId!==e.pointerId)return;const g=elementGesture,dx=(e.clientX-g.startX)/g.zoom,dy=(e.clientY-g.startY)/g.zoom;if(Math.hypot(dx,dy)<2&&!g.moved)return;g.moved=true;e.preventDefault();if(g.type==='logo-width'){const logo={...g.startLogo,width:g.startLogo.width+dx};clampLogo(logo);g.finalLogo=logo;updateLogoPreview(logo);return}if(g.type==='scale'){const next=Math.max(.2,Math.min(4,g.startScale+(dx+dy)/240));g.finalOverride={...g.startOverride,scale:next};applyElementOverride(g.el,g.finalOverride);const output=$('[data-element-prop="scale"]')?.closest('label')?.querySelector('output');if(output)output.textContent=elementOutput('scale',next);return}let moveX=Math.max(g.bounds.minX,Math.min(g.bounds.maxX,dx)),moveY=Math.max(g.bounds.minY,Math.min(g.bounds.maxY,dy));({moveX,moveY}=snapElementMove(g,moveX,moveY));g.finalOverride={...g.startOverride,x:(Number(g.startOverride.x)||0)+moveX,y:(Number(g.startOverride.y)||0)+moveY};applyElementOverride(g.el,g.finalOverride)}
function handlePointerUp(e){if(!elementGesture||e?.pointerId!==undefined&&elementGesture.pointerId!==e.pointerId)return;const g=elementGesture;elementGesture=null;hideAlignmentGuides();if(!g.moved)return;if(g.type==='logo-width'){const finalLogo=g.finalLogo||g.startLogo;store.commit('Logo redimensionné',p=>Object.assign(getSlideLogo(p.slides[p.activeSlideIndex]),finalLogo),'logo-change');showToast(`Logo ajusté à ${Math.round(finalLogo.width)} px`,'success');return}const finalOverride=g.finalOverride||g.startOverride;store.commit(g.type==='scale'?'Élément redimensionné':'Élément déplacé',p=>setElementOverride(p.slides[p.activeSlideIndex],g.id,finalOverride),'element-change')}

function clampZoom(percent){return Math.max(ZOOM_MIN,Math.min(ZOOM_MAX,Math.round(Number(percent)/ZOOM_STEP)*ZOOM_STEP))}
function getFitZoomScale(){const p=store.project,shell=$('#canvasShell');if(!shell)return .75;return Math.max(ZOOM_MIN/100,Math.min(ZOOM_MAX/100,(shell.clientWidth-64)/p.format.width,(shell.clientHeight-64)/p.format.height))}
function setZoomPercent(percent){store.project.ui=store.project.ui||{};store.project.ui.zoomMode='custom';store.project.ui.zoomValue=clampZoom(percent)/100;applyZoom()}
function setZoomFit(){store.project.ui=store.project.ui||{};store.project.ui.zoomMode='fit';applyZoom()}
function stepZoom(direction){const current=Math.round((Number(store.project.ui?.zoomValue)||getFitZoomScale())*100);setZoomPercent(current+direction*ZOOM_STEP)}
function applyZoom(){const p=store.project,ui=p.ui||(p.ui={});const scale=ui.zoomMode==='custom'?Math.max(ZOOM_MIN/100,Math.min(ZOOM_MAX/100,Number(ui.zoomValue)||.75)):getFitZoomScale();ui.zoomValue=scale;const percent=Math.round(scale*100);const range=$('#zoomRange'),value=$('#zoomValue'),fit=$('#zoomFitButton'),canvas=$('#studio-canvas');if(range)range.value=String(clampZoom(percent));if(value)value.textContent=`${percent} %`;if(fit){fit.classList.toggle('is-active',ui.zoomMode!=='custom');fit.setAttribute('aria-pressed',String(ui.zoomMode!=='custom'))}if(canvas)canvas.style.transform=`scale(${scale})`}
function previewInspectorProperty(input){const id=store.project.ui?.selectedElementId;if(!id)return;const prop=input.dataset.elementProp,value=normalizedElementProperty(prop,input.value);previewElementOverride($('#studio-canvas'),id,{[prop]:value});const output=input.closest('label')?.querySelector('output');if(output)output.textContent=elementOutput(prop,value)}
function commitInspectorProperty(input){const id=store.project.ui?.selectedElementId;if(!id)return;const prop=input.dataset.elementProp,value=normalizedElementProperty(prop,input.value);store.commit('Propriété de l’élément modifiée',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{[prop]:value}),'element-change')}
function setSelectedLayer(front=true){const id=store.project.ui?.selectedElementId;if(!id)return;store.commit(front?'Élément placé au premier plan':'Élément placé à l’arrière-plan',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{zIndex:front?50:0}),'element-change')}
function resetSelectedElement(){const id=store.project.ui?.selectedElementId;if(!id)return;store.commit('Réglages de l’élément réinitialisés',p=>resetElementOverride(p.slides[p.activeSlideIndex],id),'element-change');showToast('Élément remis à sa position et sa taille d’origine','success')}
function nudgeSelectedElement(dx,dy){const id=store.project.ui?.selectedElementId;if(!id||!selectedCanvasElement(id))return;store.commit('Élément déplacé au clavier',p=>{const slide=p.slides[p.activeSlideIndex],current=getElementOverride(slide,id);setElementOverride(slide,id,{x:(Number(current.x)||0)+dx,y:(Number(current.y)||0)+dy})},'element-change')}
async function handleClick(e){const a=e.target.dataset.action;const model=e.target.closest?.('[data-template-id]');if(model&&!model.closest('#studio-canvas'))setTemplate(model.dataset.templateId);if(e.target.dataset.slide)store.setSlide(Number(e.target.dataset.slide));const canvasElement=e.target.closest?.('#studio-canvas [data-studio-element-id]');if(canvasElement)selectElement(canvasElement);if(a==='differentComposition')chooseDifferentComposition();if(a==='zoomOut')stepZoom(-1);if(a==='zoomIn')stepZoom(1);if(a==='zoomFit')setZoomFit();if(a==='autoFix'){await renderActiveSlide();showToast('Mise en page recalée automatiquement','success')}if(a==='openExport')$('#exportDialog').showModal();if(a==='closeExport')$('#exportDialog').close();if(a==='exportStandard')await doExport(1);if(a==='exportHd')await doExport(2);if(a==='save')await saveStudioProject();if(a==='undo')store.undo();if(a==='redo')store.redo();if(a==='addSlide')store.commit('Slide ajoutée',p=>{p.slides.push(normalizeSlide({formation:p.formation,templateId:getActiveSlide().templateId}));p.activeSlideIndex=p.slides.length-1});if(a==='logoOfficial')store.commit('Logo officiel restauré',p=>{p.branding.logoUrl=window.STUDIO_BOOTSTRAP.officialLogoUrl;p.branding.logoName='Logo officiel Intégrale Academy';p.branding.logoVisible=true},'logo-change');if(a==='logoDelete')store.commit('Logo masqué',p=>{p.branding.logoVisible=false});if(a==='logoSmaller')changeLogoSize(-10,'Logo réduit');if(a==='logoLarger')changeLogoSize(10,'Logo agrandi');if(a==='logoReset')store.commit('Taille idéale du logo restaurée',p=>Object.assign(getSlideLogo(p.slides[p.activeSlideIndex]),DEFAULT_LOGO_SETTINGS),'logo-change');if(a==='logoFit')store.commit('Logo mis en avant',p=>Object.assign(getSlideLogo(p.slides[p.activeSlideIndex]),{width:240,opacity:1}),'logo-change');if(a==='elementBackward')setSelectedLayer(false);if(a==='elementForward')setSelectedLayer(true);if(a==='elementReset')resetSelectedElement();const iconButton=e.target.closest?.('[data-add-icon]');if(iconButton){store.commit('Pictogramme ajouté',p=>{const slide=p.slides[p.activeSlideIndex];slide.elements=slide.elements||[];slide.elements.push({id:crypto.randomUUID(),type:'icon',label:iconButton.dataset.addIcon,x:120+slide.elements.length*28,y:120+slide.elements.length*28})});showToast('Pictogramme ajouté','success')}if(e.target.dataset.ai){try{const j=await studioFetch('/api/admin/social-visuals/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:$('#aiTopic')?.value||'',action:e.target.dataset.ai,project:store.project})});const clean=sanitizeAiPayload(j.content||j);store.commit('Contenu IA généré',p=>{p.name=clean.projectTitle;p.formation=clean.formation;Object.assign(p.slides[p.activeSlideIndex].content,clean.content)});showToast('Contenu IA généré','success')}catch(err){showToast(`IA impossible : ${err.message}`,'error')}}}
function handleInput(e){if(e.target.dataset.elementProp)previewInspectorProperty(e.target);if(e.target.dataset.logoProp){const logo={...getSlideLogo(),[e.target.dataset.logoProp]:Number(e.target.value)};clampLogo(logo);updateLogoPreview(logo)}if(e.target.id==='zoomRange')setZoomPercent(e.target.value);if(e.target.id==='projectName')store.project.name=e.target.value}
function handleChange(e){if(e.target.dataset.content)setContentValue(e.target.dataset.content,e.target.value);if(e.target.dataset.elementProp)commitInspectorProperty(e.target);if(e.target.dataset.logoProp)store.commit('Logo modifié',p=>{const logo=getSlideLogo(p.slides[p.activeSlideIndex]);logo[e.target.dataset.logoProp]=Number(e.target.value);clampLogo(logo)},'logo-change');if(e.target.dataset.elementText){const id=store.project.ui?.selectedElementId,key=e.target.dataset.elementContentKey,value=e.target.value;if(key)setContentValue(key,value,'Texte modifié');else if(id)store.commit('Texte modifié',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{text:value}),'element-change')}if(e.target.id==='inspectorFormation'||e.target.id==='brandFormation')setFormation(e.target.value);if(e.target.id==='inspectorTemplate')setTemplate(e.target.value);if(e.target.id==='formatSelect')store.commit('Format changé',p=>p.format=FORMATS[e.target.value]);if(e.target.id==='showLogo')store.commit('Logo affiché/masqué',p=>p.branding.logoVisible=e.target.checked);if(e.target.id==='showSafe')store.commit('Marges affichées/masquées',p=>p.slides[p.activeSlideIndex].options.showSafeMargins=e.target.checked);if(e.target.id==='logoInput'&&e.target.files?.[0])importLogo(e.target.files[0]).catch(err=>showToast(`Import impossible : ${err.message}`,'error'))}
function handleStudioEnhancementClick(e){const emojiButton=e.target.closest?.('[data-add-emoji]'),promptButton=e.target.closest?.('[data-ai-design-prompt]'),action=e.target.closest?.('[data-action]')?.dataset.action;if(emojiButton){const glyph=emojiButton.dataset.addEmoji;store.commit('Emoji ajouté',p=>{const slide=p.slides[p.activeSlideIndex],count=(slide.elements||[]).length;slide.elements=slide.elements||[];slide.elements.push({id:crypto.randomUUID(),type:'emoji',glyph,label:`Emoji ${glyph}`,x:130+(count%5)*34,y:160+(count%4)*42,fontSize:72})},'element-add');showToast(`${glyph} ajouté au template`,'success')}if(promptButton){const input=$('#aiDesignPrompt');if(input){input.value=promptButton.dataset.aiDesignPrompt;input.focus()}}if(action==='applyAiDesign')applyAiDesignPrompt();if(action==='resetAiDesign')resetAiDesign()}
function handleStudioEnhancementChange(e){if(e.target.id==='visualInput'&&e.target.files?.[0])importVisual(e.target.files[0]).catch(err=>showToast(`Import impossible : ${err.message}`,'error'))}
function handleKeydown(e){if(editing){if(e.key==='Escape'){e.preventDefault();cancelInlineTextEdit()}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();commitInlineTextEdit(editing.el)}return}if(e.key==='Enter'&&document.activeElement?.dataset?.studioTextEditable==='true'){startInlineTextEdit(document.activeElement);return}const formControl=e.target.closest?.('input,textarea,select,[contenteditable]');if(formControl||e.ctrlKey||e.metaKey||e.altKey)return;const amount=e.shiftKey?10:1;if(e.key==='ArrowLeft'){e.preventDefault();nudgeSelectedElement(-amount,0)}if(e.key==='ArrowRight'){e.preventDefault();nudgeSelectedElement(amount,0)}if(e.key==='ArrowUp'){e.preventDefault();nudgeSelectedElement(0,-amount)}if(e.key==='ArrowDown'){e.preventDefault();nudgeSelectedElement(0,amount)}if(e.key==='+'||e.key==='='){e.preventDefault();stepZoom(1)}if(e.key==='-'){e.preventDefault();stepZoom(-1)}if(e.key==='0'){e.preventDefault();setZoomFit()}}
document.addEventListener('click',handleStudioEnhancementClick);document.addEventListener('change',handleStudioEnhancementChange);document.addEventListener('dblclick',e=>{const element=e.target.closest?.('#studio-canvas [data-studio-element-id]');if(element?.dataset.studioTextEditable==='true')startInlineTextEdit(element)});document.addEventListener('focusout',e=>{if(editing?.el===e.target)commitInlineTextEdit(e.target)});document.addEventListener('paste',e=>{if(editing){e.preventDefault();document.execCommand('insertText',false,(e.clipboardData||window.clipboardData).getData('text'))}});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
